import{c as a,Q as e,j as s,m as l}from"./chunks/framework.DOi4mjdC.js";const _=JSON.parse('{"title":"TRACE_START","description":"","frontmatter":{},"headers":[{"level":1,"title":"TRACE\\\\_START","slug":"trace_start"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/Utils-API/调测接口/TRACE_START.md","filePath":"api/Utils-API/调测接口/TRACE_START.md"}'),n={name:"api/Utils-API/调测接口/TRACE_START.md"};function i(d,t,r,p,o,c){return e(),s("div",null,[...t[0]||(t[0]=[l(`<h1 id="trace-start" tabindex="-1">TRACE_START <a class="header-anchor" href="#trace-start" aria-label="Permalink to &quot;TRACE\\_START&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>√</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>√</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>√</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>通过CAModel进行算子性能仿真时，可对算子任意运行阶段打点，从而分析不同指令的流水图，以便进一步性能调优。</p><p>用于表示起始位置打点，一般与<a href="./TRACE_STOP.html">TRACE_STOP</a>配套使用。</p><div class="caution custom-block github-alert"><p class="custom-block-title">注意</p><p>该功能主要用于<strong>调试和性能分析</strong>，开启后会对算子性能产生一定影响，通常在调测阶段使用，<strong>生产环境建议关闭</strong>。 默认情况下，该功能关闭，开发者可以按需通过如下方式开启打点功能。 修改Kernel直调工程cmake目录下的npu_lib.cmake文件，在ascendc_compile_definitions命令中增加-DASCENDC_TRACE_ON编译选项，来开启打点功能。示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 打开算子的打点功能</span></span>
<span class="line"><span>ascendc_compile_definitions(ascendc_kernels_\${RUN_MODE} PRIVATE</span></span>
<span class="line"><span>   -DASCENDC_TRACE_ON</span></span>
<span class="line"><span>)</span></span></code></pre></div></div><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#define TRACE_START(TraceId apid)</span></span>
<span class="line"><span>#define TRACE_START(pipe_t pipe, TraceId apid)</span><span> // 该接口仅支持Ascend 950PR/Ascend 950DT</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>apid</td><td>输入</td><td>当前预留了十个用户自定义的类型： 0x0：USER_DEFINE_00x1：USER_DEFINE_10x2：USER_DEFINE_20x3：USER_DEFINE_30x4：USER_DEFINE_40x5：USER_DEFINE_50x6：USER_DEFINE_60x7：USER_DEFINE_70x8：USER_DEFINE_80x9：USER_DEFINE_9</td></tr><tr><td>pipe</td><td>输入</td><td>指定打点所在的pipeline类型。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>TRACE_START/TRACE_STOP需配套使用，若Trace图上未显示打点，则说明两者没有配对。</li><li>不支持跨核使用，例如TRACE_START在AI Cube打点，则TRACE_STOP打点也需要在AI Cube上，不能在AI Vector上。</li><li>宏支持所有的产品型号，但实际调用时需与调测工具支持的型号保持一致。</li><li>仅支持Kernel直调工程，不支持自定义算子工程下开启打点功能。</li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>在Kernel代码中特定指令位置打上TRACE_START/TRACE_STOP：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TRACE_START(0x2);</span></span>
<span class="line"><span>Add(zLocal, xLocal, yLocal, dataSize);</span></span>
<span class="line"><span>TRACE_STOP(0x2);</span></span></code></pre></div>`,18)])])}const A=a(n,[["render",i]]);export{_ as __pageData,A as default};
